package net.nexus.app.ui

import android.util.Base64
import java.nio.ByteBuffer

/**
 * Authentic equal-area Fibonacci land matrix derived from Natural Earth 110m.
 * Encoded compactly as Base64 16-bit fixed-point coordinates (4062 points).
 */
internal val GLOBE_LAND_POINTS: FloatArray by lazy {
    val raw = Base64.decode(LAND_DATA_B64, Base64.DEFAULT)
    val buf = ByteBuffer.wrap(raw).asShortBuffer()
    val arr = FloatArray(buf.remaining())
    var i = 0
    while (buf.hasRemaining()) {
        arr[i++] = buf.get() / 100f
    }
    arr
}

private const val LAND_DATA_B64 = ""
